"""One read-only Joy partition check. No source/runtime generation."""
from pathlib import Path
import sys,json,hashlib
import numpy as np
ROOT=Path(__file__).resolve().parents[3];OUT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'scripts/m2-male-face-v1'))
from glb import GLB
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
spec=json.loads((ROOT/'assets-source/face-eye-sample-v1/spec.json').read_text());selection=json.loads((ROOT/'assets-source/face-eye-sample-v1/selection.json').read_text());rows=[];deps=[Path(__file__)];h=.65;b=.998971
for sex,src in spec['bodies'].items():
 path=ROOT/src['sourceVRM'];assert sha(path)==src['sourceVRMSha256'];deps.append(path);g=GLB(path);mesh=g.doc['meshes'][1];p=mesh['primitives'][0];names=mesh['extras']['targetNames'];keys=['ALL_Joy','BRW_Joy','EYE_Joy','MTH_Joy','MTH_A'];ids={k:next(i for i,n in enumerate(names)if n.endswith('_'+k))for k in keys};d={k:g.acc(p['targets'][i]['POSITION']).astype(float)for k,i in ids.items()};res=d['ALL_Joy']-d['BRW_Joy']-d['EYE_Joy']-d['MTH_Joy'];norm=np.linalg.norm(res,axis=1);bad=np.flatnonzero(norm>0);eye=np.flatnonzero(np.linalg.norm(d['EYE_Joy'],axis=1)>0);mouth=ROOT/selection['bodies'][sex]['existingRecipes']['mouth']['path'];assert sha(mouth)==selection['bodies'][sex]['existingRecipes']['mouth']['sha256'];deps.append(mouth);mr=json.loads(mouth.read_text());mouthDomain=np.flatnonzero(np.array(mr['weights'])!=0);browIds=np.unique(np.concatenate([g.acc(pr['indices']).ravel()for pr in mesh['primitives']if 'FaceBrow'in g.doc['materials'][pr['material']]['name']]));mouthIds=np.unique(np.concatenate([g.acc(pr['indices']).ravel()for pr in mesh['primitives']if 'FaceMouth'in g.doc['materials'][pr['material']]['name']]));protect=np.union1d(np.union1d(browIds,mouthIds),mouthDomain)
 # Proposed exact decomposition, arrays evaluated only, NEVER exported as morphs.
 E=d['EYE_Joy'].copy();E[protect]=0;R=d['ALL_Joy']-E;neutralResidual=float(np.abs(R+E-d['ALL_Joy']).max());change=-h*b*E
 layer=[]
 for pr in mesh['primitives']:
  v=np.unique(g.acc(pr['indices']));layer.append({'material':g.doc['materials'][pr['material']]['name'],'count':len(v),'sumResidualMaxM':float(norm[v].max()),'sumResidualNonzeroIDs':[int(i)for i in v if norm[i]>0],'partitionMaxM':{k:float(np.linalg.norm(d[k][v],axis=1).max())for k in keys},'eyeMovedIDs':[int(i)for i in v if i in eye],'proposedEyeCorrectionMaxM':float(np.linalg.norm(change[v],axis=1).max())})
 groups=g.doc['extensions']['VRM']['blendShapeMaster']['blendShapeGroups'];mapped={k:[{'preset':x['presetName'],'name':x['name']}for x in groups if any(y.get('mesh')==1 and y.get('index')==i for y in x.get('binds',[]))]for k,i in ids.items()}
 rows.append({'sex':sex,'sourceSha256':sha(path),'targetMapping':{k:{'index':i,'name':names[i],'VRM0Groups':mapped[k]}for k,i in ids.items()},'sumResidualMaxM':float(norm.max()),'sumExact':bool((norm==0).all()),'residualPoints':[{'index':int(i),'vector':res[i].tolist(),'lengthM':float(norm[i])}for i in bad],'layers':layer,'eyeIntersection':{'mouthGeometryDomain':np.intersect1d(eye,mouthDomain).tolist(),'faceMouthMaterial':np.intersect1d(eye,mouthIds).tolist(),'faceBrowMaterial':np.intersect1d(eye,browIds).tolist(),'MTH_JoyNonzeroSupport':np.intersect1d(eye,np.flatnonzero(np.linalg.norm(d['MTH_Joy'],axis=1)>0)).tolist(),'MTH_ANonzeroSupport':np.intersect1d(eye,np.flatnonzero(np.linalg.norm(d['MTH_A'],axis=1)>0)).tolist()},'exactMaskedProposal':{'equation':'E=EYE_Joy with explicit protected FaceBrow/FaceMouth/mouth geometry domain zeroed; R=ALL_Joy-E; P=Basis+h*R+h*(1-b)*E+b*Close+a*A.','unblinkReconstructionMaxComponentM':neutralResidual,'protectedCount':len(protect),'protectedChangeMaxM':float(np.linalg.norm(change[protect],axis=1).max()),'eyeNonzeroAfterMask':int((np.linalg.norm(E,axis=1)>0).sum()),'aaTargetChanged':False,'note':'Read-only arrays. Derived split binds are not present in current VRM0 expression manager; no generated source/attribute or installed control.'}})
r={'scope':'Supplement only: all original Face points and per material Joy shape partition, no source/runtime modification.','bodies':rows,'dependencies':[{'path':p.relative_to(ROOT).as_posix(),'sha256':sha(p)}for p in deps]};(OUT/'report.json').write_text(json.dumps(r,indent=2)+'\n',encoding='utf-8');print(json.dumps([{'sex':x['sex'],'residual':x['sumResidualMaxM'],'intersections':x['eyeIntersection'],'proposal':x['exactMaskedProposal']}for x in rows],indent=2))
